// Génère un brief SEO pour l'article
const topics = [
  { sector: 'PME', geo: 'Vaud', keywords: ['site web PME Vaud', 'création site internet Lausanne', 'agence web Vaud'], intent: 'commercial' },
  { sector: 'E-commerce', geo: 'Genève', keywords: ['boutique en ligne Genève', 'e-commerce Suisse', 'vente en ligne Genève'], intent: 'commercial' },
  { sector: 'Startup', geo: 'Romandie', keywords: ['startup digitale Suisse', 'MVP développement', 'tech startup Romandie'], intent: 'informatif' },
  { sector: 'Automatisation', geo: 'Suisse romande', keywords: ['automatisation workflow', 'n8n Suisse', 'processus automatisation'], intent: 'informatif' },
  { sector: 'SEO', geo: 'Lausanne', keywords: ['référencement Lausanne', 'SEO local Suisse', 'visibilité Google Suisse'], intent: 'informatif' }
];

// Sélection aléatoire d'un topic
const selectedTopic = topics[Math.floor(Math.random() * topics.length)];

return {
  json: {
    sector: selectedTopic.sector,
    geo: selectedTopic.geo,
    keywords: selectedTopic.keywords,
    intent: selectedTopic.intent,
    generation_date: new Date().toISOString()
  }
};

// Parse la réponse JSON de Claude
const claudeResponse = $json.output || $json.response || '{}';
let articleData;

try {
  let cleanJson = claudeResponse;
  if (typeof claudeResponse === 'string') {
    cleanJson = claudeResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  }
  articleData = typeof cleanJson === 'string' ? JSON.parse(cleanJson) : cleanJson;
} catch (e) {
  throw new Error('Failed to parse Claude response: ' + e.message);
}

return { json: articleData };

